from pathlib import Path
from remote import upload,call
files=[(Path('work/hand-qwen-transfer/capture.py'),'capture.py'),(Path('work/hand-motion/recording.py'),'recording.py')]
upload(files)
print(call("python - <<'REMOTE'\nimport ast,json,os,subprocess,signal,time\nfrom pathlib import Path\nr=Path('/opt/BrickSim/.runtime/hand-qwen-transfer');template=Path('/opt/BrickSim/.runtime/hand-motion/supervisor.py').read_text();node=next(n.value for n in ast.parse(template).body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='command' for x in n.targets));root=r;snapshot=r;command=eval(compile(ast.Expression(node),'command','eval')).replace(str(r/'session.py:main'),str(r/'capture.py:main'));runner='''import os,signal,subprocess,time,json\nfrom pathlib import Path\nr=Path(%r)\nwith (r/'capture.log').open('w') as f:\n p=subprocess.Popen(['bash','-c',%r],stdout=f,stderr=subprocess.STDOUT,start_new_session=True,env=dict(os.environ,OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',MKL_NUM_THREADS='1'))\n (r/'capture-owned.json').write_text(json.dumps({'group':p.pid}))\n try:p.wait(timeout=900)\n except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGTERM);p.wait(timeout=15)\n (r/'capture-cleanup.json').write_text(json.dumps({'stopped':p.poll() is not None,'returncode':p.returncode}))\n'''%(str(r),command);(r/'capture-supervisor.py').write_text(runner);p=subprocess.Popen(['python',str(r/'capture-supervisor.py')],stdout=open(r/'capture-supervisor.log','w'),stderr=subprocess.STDOUT,start_new_session=True);print('CAPTURE_SUPERVISOR',p.pid)\nREMOTE\n")[-500:])
